-- Objects with the properties Script as CREATE must recreate or warn about.
-- script-hostile-pg-prelude.sql makes what no table script makes.
CREATE SCHEMA "Weird ""S""";
CREATE SCHEMA app;
CREATE SCHEMA "order";
CREATE COLLATION app."my coll" (provider = icu, locale = 'sv-SE');
CREATE DOMAIN app.posint AS integer CHECK (VALUE > 0);
CREATE TYPE app.mood AS ENUM ('ok', 'sad');
CREATE TYPE app.pet AS (id int, kind text, name text);
CREATE FOREIGN DATA WRAPPER hostile_fdw;
CREATE SERVER hostile_server FOREIGN DATA WRAPPER hostile_fdw;
CREATE FUNCTION app."Trg Fn"() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;

CREATE TABLE "Weird ""S""".parent (
  "Id" integer GENERATED ALWAYS AS IDENTITY (START WITH 5 INCREMENT BY 3 MINVALUE 2 MAXVALUE 1000 CACHE 7 CYCLE) PRIMARY KEY,
  "between" text,
  "int" int,
  "time" time,
  "values" text,
  "a""b c" text COLLATE app."my coll",
  "user" text,
  "char" text,
  down smallint GENERATED BY DEFAULT AS IDENTITY (INCREMENT BY -1),
  s serial,
  p app.posint,
  moods app.mood[],
  note text DEFAULT E'it''s \\ back',
  packed text COMPRESSION lz4,
  CONSTRAINT "Chk ""x""" CHECK (char_length("between") < 100)
);
COMMENT ON TABLE "Weird ""S""".parent IS E'quote '' backslash \\ newline\nend';
COMMENT ON COLUMN "Weird ""S""".parent."a""b c" IS 'col comment';
COMMENT ON CONSTRAINT "Chk ""x""" ON "Weird ""S""".parent IS 'constraint comment';
COMMENT ON INDEX "Weird ""S""".parent_pkey IS 'pkey comment';
COMMENT ON CONSTRAINT parent_pkey ON "Weird ""S""".parent IS 'pkey constraint comment';
CREATE INDEX "Idx One" ON "Weird ""S""".parent ("between", "int");
COMMENT ON INDEX "Weird ""S"""."Idx One" IS 'index comment';
CREATE TRIGGER "Trg ""1""" BEFORE INSERT ON "Weird ""S""".parent FOR EACH ROW EXECUTE FUNCTION app."Trg Fn"();
ALTER TABLE "Weird ""S""".parent DISABLE TRIGGER "Trg ""1""";
COMMENT ON TRIGGER "Trg ""1""" ON "Weird ""S""".parent IS 'trigger comment';
CREATE RULE r_noop AS ON UPDATE TO "Weird ""S""".parent WHERE false DO INSTEAD NOTHING;
ALTER TABLE "Weird ""S""".parent DISABLE RULE r_noop;
COMMENT ON RULE r_noop ON "Weird ""S""".parent IS 'rule comment';
ALTER TABLE "Weird ""S""".parent REPLICA IDENTITY FULL;
CLUSTER "Weird ""S""".parent USING "Idx One";
ALTER TABLE "Weird ""S""".parent ALTER COLUMN "values" SET STATISTICS 500;
ALTER TABLE "Weird ""S""".parent ALTER COLUMN "user" SET STORAGE EXTERNAL;
ALTER TABLE "Weird ""S""".parent ALTER COLUMN "char" SET (n_distinct = 5);
ALTER TABLE "Weird ""S""".parent ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Weird ""S""".parent FORCE ROW LEVEL SECURITY;
CREATE POLICY "Own ""rows""" ON "Weird ""S""".parent AS RESTRICTIVE FOR UPDATE TO pg_read_all_data USING ("Id" > 0) WITH CHECK ("int" < 10);
CREATE POLICY everyone ON "Weird ""S""".parent USING (true);
COMMENT ON POLICY everyone ON "Weird ""S""".parent IS 'policy comment';
CREATE STATISTICS app.parent_stats (ndistinct, dependencies) ON "between", "int" FROM "Weird ""S""".parent;
ALTER STATISTICS app.parent_stats SET STATISTICS 50;
COMMENT ON STATISTICS app.parent_stats IS 'stats comment';

-- legacy inheritance: a merged column, a merged check, a changed default, and a column added after
CREATE TABLE app.base (id int DEFAULT 1, note text NOT NULL, CONSTRAINT base_pos CHECK (id > 0));
CREATE TABLE app.child (extra text, note text, CONSTRAINT base_pos CHECK (id > 0)) INHERITS (app.base);
ALTER TABLE app.child ALTER COLUMN id SET DEFAULT 2;
ALTER TABLE app.child ALTER COLUMN id SET NOT NULL;
ALTER TABLE app.base ADD COLUMN late int;
CREATE TABLE app.other_base (tag text);
CREATE TABLE app.twice () INHERITS (app.base, app.other_base);

-- a partition tree three levels deep, with partitions' own properties and a foreign partition
CREATE TABLE app.ev (id int NOT NULL, k text NOT NULL, d date NOT NULL, v int DEFAULT 7) PARTITION BY LIST (k);
CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES IN ('a') PARTITION BY RANGE (d);
CREATE UNLOGGED TABLE app.ev_a_2026 PARTITION OF app.ev_a FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE INDEX ev_a_2026_local ON app.ev_a_2026 (v);
ALTER TABLE app.ev_a_2026 ADD CONSTRAINT ev_a_2026_chk CHECK (v > 0);
ALTER TABLE app.ev_a_2026 ALTER COLUMN v SET DEFAULT 9;
COMMENT ON TABLE app.ev_a_2026 IS 'leaf';
CREATE TABLE app.ev_b (id int NOT NULL, k text NOT NULL, d date NOT NULL, v int);
ALTER TABLE app.ev ATTACH PARTITION app.ev_b FOR VALUES IN ('b');
ALTER TABLE app.ev_b ALTER COLUMN v SET NOT NULL;
CREATE FOREIGN TABLE app.ev_remote PARTITION OF app.ev FOR VALUES IN ('r') SERVER hostile_server OPTIONS (table_name 'ev, remote', "Odd" 'it''s');
ALTER FOREIGN TABLE app.ev_remote ALTER COLUMN v OPTIONS (ADD column_name 'vv');
CREATE TABLE app.ev_def PARTITION OF app.ev DEFAULT;
CREATE INDEX ev_def_local ON app.ev_def (id);
ALTER TABLE app.ev_def ADD CONSTRAINT ev_def_chk CHECK (id < 100);

-- a standalone foreign table
CREATE FOREIGN TABLE app.remote (id int NOT NULL, label text OPTIONS (column_name 'lbl')) SERVER hostile_server OPTIONS (schema_name 'x');

-- serial->identity migration leftover
CREATE TABLE app.mig (id integer NOT NULL);
CREATE SEQUENCE app.mig_old_seq START 777 OWNED BY app.mig.id;
ALTER TABLE app.mig ALTER id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 1);
-- an identity whose sequence has its own name
CREATE TABLE app.named_identity (id bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME app.custom_identity_seq));
-- serial whose sequence was renamed and changed
CREATE TABLE app.ren (id serial PRIMARY KEY);
ALTER SEQUENCE app.ren_id_seq RENAME TO ren_custom_seq;
ALTER SEQUENCE app.ren_custom_seq INCREMENT BY 5;

-- unlogged with options and a TOAST option
CREATE UNLOGGED TABLE app.opt (a text) WITH (fillfactor = 70, toast.autovacuum_enabled = false);
-- NOT VALID foreign key, and a replica identity index
CREATE TABLE app.refd (id int PRIMARY KEY);
ALTER TABLE app.refd REPLICA IDENTITY USING INDEX refd_pkey;
CREATE TABLE app.refr (rid int);
ALTER TABLE app.refr ADD CONSTRAINT refr_fk FOREIGN KEY (rid) REFERENCES app.refd NOT VALID;
-- views
CREATE VIEW app."My View" WITH (security_barrier = true) AS SELECT "Id", "between" FROM "Weird ""S""".parent WHERE "Id" > 0 WITH LOCAL CHECK OPTION;
COMMENT ON COLUMN app."My View"."between" IS 'view col comment';
CREATE VIEW app.v_def AS SELECT 1 AS x;
ALTER VIEW app.v_def ALTER x SET DEFAULT 42;
CREATE RULE v_def_ins AS ON INSERT TO app.v_def DO INSTEAD NOTHING;
-- routines
CREATE PROCEDURE app."Proc X"(IN a int, OUT b int) LANGUAGE plpgsql AS $$BEGIN b := a; END$$;
COMMENT ON PROCEDURE app."Proc X"(int, int) IS 'proc comment';
CREATE FUNCTION app.f_atomic(a int) RETURNS int LANGUAGE sql BEGIN ATOMIC SELECT a + 1; END;
COMMENT ON FUNCTION app.f_atomic(int) IS 'atomic';
CREATE FUNCTION app.f_out(a int, OUT b int, OUT c int) LANGUAGE sql AS 'SELECT a, a';
COMMENT ON FUNCTION app.f_out(int) IS 'outs';
-- a table named with a reserved word, with privileges no script grants
CREATE TABLE app."select" ("from" int, "Mixed" int);
GRANT SELECT ON app."select" TO pg_read_all_data;
GRANT UPDATE ("Mixed") ON app."select" TO pg_read_all_data;
GRANT USAGE ON SEQUENCE app.ren_custom_seq TO pg_read_all_data;
CREATE FUNCTION app.sec_def(int) RETURNS int LANGUAGE sql SECURITY DEFINER AS 'SELECT 1';
REVOKE EXECUTE ON FUNCTION app.sec_def(int) FROM PUBLIC;
-- matview not populated, with a clustered index and column statistics
CREATE MATERIALIZED VIEW app.mv WITH (fillfactor = 50) AS SELECT 1 AS x WITH NO DATA;
CREATE UNIQUE INDEX mv_x ON app.mv (x);
ALTER MATERIALIZED VIEW app.mv CLUSTER ON mv_x;
ALTER MATERIALIZED VIEW app.mv ALTER COLUMN x SET STATISTICS 200;
COMMENT ON COLUMN app.mv.x IS 'mv col comment';
CREATE TABLE "order"."group" (id int);
CREATE TABLE app.pets OF app.pet (kind WITH OPTIONS DEFAULT 'cat' NOT NULL, name WITH OPTIONS NOT NULL, PRIMARY KEY (id));
CREATE TABLE app.bare_pets OF app.pet;
CREATE INDEX "Lower a" ON app.opt ((lower(a)));
ALTER INDEX app."Lower a" ALTER COLUMN 1 SET STATISTICS 300;
CREATE TABLE app.pt (k int) PARTITION BY LIST (k);
CREATE TABLE app.pt1 PARTITION OF app.pt FOR VALUES IN (1);
CREATE INDEX pt_only ON ONLY app.pt (k);
CREATE PUBLICATION hostile_pub FOR TABLE app.refd;
CREATE TABLE app.dups (v int);
INSERT INTO app.dups VALUES (1), (1);
CREATE TABLE app.tree (id int NOT NULL, parent int);
CREATE UNIQUE INDEX tree_id ON app.tree (id);
ALTER TABLE app.tree ADD CONSTRAINT tree_parent FOREIGN KEY (parent) REFERENCES app.tree (id);
CREATE TABLE app.ri (id int NOT NULL, k int NOT NULL) PARTITION BY LIST (k);
CREATE UNIQUE INDEX ri_id_k ON app.ri (id, k);
CREATE TRIGGER ri_trg AFTER INSERT ON app.ri FOR EACH ROW EXECUTE FUNCTION app."Trg Fn"();
CREATE TABLE app.ri_1 PARTITION OF app.ri FOR VALUES IN (1);
CREATE TABLE app.ri_2 PARTITION OF app.ri FOR VALUES IN (2);
ALTER INDEX app.ri_1_id_k_idx RENAME TO "ri_1 custom";
ALTER TABLE app.ri_1 REPLICA IDENTITY USING INDEX "ri_1 custom";
ALTER TABLE app.ri_1 DISABLE TRIGGER ri_trg;
COMMENT ON TRIGGER ri_trg ON app.ri_2 IS 'leaf clone note';
ALTER TABLE app.ri_2 CLUSTER ON ri_2_id_k_idx;
COMMENT ON INDEX app.ri_2_id_k_idx IS 'leaf index note';
CREATE TABLE app.gen (a int, b int GENERATED ALWAYS AS (a * 2) STORED) PARTITION BY LIST (a);
CREATE TABLE app.gen_1 (a int, b int GENERATED ALWAYS AS (a * 3) STORED);
ALTER TABLE app.gen ATTACH PARTITION app.gen_1 FOR VALUES IN (1);
CREATE TABLE app.gen_2 PARTITION OF app.gen FOR VALUES IN (2);
CREATE TABLE app.pa (a int DEFAULT 1);
CREATE TABLE app.pb (a int DEFAULT 2);
CREATE TABLE app.pab (a int DEFAULT 3) INHERITS (app.pa, app.pb);
CREATE TABLE app.idp (id int GENERATED ALWAYS AS IDENTITY, k int NOT NULL) PARTITION BY LIST (k);
CREATE TABLE app.idp_1 PARTITION OF app.idp FOR VALUES IN (1);
CREATE TABLE app.plain (id int);
CREATE TABLE app.kid (id int GENERATED BY DEFAULT AS IDENTITY) INHERITS (app.plain);
